// A profile's lower-case name for an icon (Icon::None when unknown).
inline Icon icon_named(const std::string& name) {
    if (name == "save") return Icon::Save;
    if (name == "load") return Icon::Load;
    if (name == "sun") return Icon::Sun;
    if (name == "moon") return Icon::Moon;
    if (name == "sleep") return Icon::Sleep;
    if (name == "power") return Icon::Power;
    if (name == "info") return Icon::Info;
    if (name == "clock") return Icon::Clock;
    if (name == "heart") return Icon::Heart;
    if (name == "key") return Icon::Key;
    if (name == "touch") return Icon::Touch;
    if (name == "check") return Icon::Check;
    if (name == "back") return Icon::Back;
    if (name == "home") return Icon::Home;
    if (name == "play") return Icon::Play;
    if (name == "sliders") return Icon::Sliders;
    if (name == "spark") return Icon::Spark;
    if (name == "controller") return Icon::Controller;
    if (name == "cartridge") return Icon::Cartridge;
    if (name == "battery") return Icon::Battery;
    if (name == "library") return Icon::Library;
    if (name == "coin") return Icon::Coin;
    if (name == "life") return Icon::Life;
    if (name == "star") return Icon::Star;
    if (name == "treasure") return Icon::Treasure;
    if (name == "bank") return Icon::Bank;
    if (name == "flag") return Icon::Flag;
    if (name == "map") return Icon::Map;
    if (name == "gem") return Icon::Gem;
    if (name == "sword") return Icon::Sword;
    if (name == "bag") return Icon::Bag;
    if (name == "more") return Icon::More;
    if (name == "close") return Icon::Close;
    if (name == "trophy") return Icon::Trophy;
    if (name == "shield") return Icon::Shield;
    return Icon::None;
}

